export const GLOSSARY_SHARD = Object.freeze({"satoshi":{"slug":"satoshi","cat":"basics","en":"Satoshi (sats)","contentLocale":"vi","term":"Satoshi (sats)","aka":["sats","sat","satoshi"],"short":"Satoshi (sats) là đơn vị nhỏ nhất của Bitcoin, với 1 BTC bằng 100.000.000 satoshi, giúp bạn mua và chuyển những phần rất nhỏ của một đồng BTC.","body":[["Tên gọi satoshi lấy từ Satoshi Nakamoto, người tạo ra ",["Bitcoin","bitcoin"],". Một satoshi là 0,00000001 BTC. Thay vì viết những con số có nhiều chữ số 0, nhiều ví và cộng đồng dùng sats cho dễ đọc, ví dụ 25.000 sats thay vì 0,00025 BTC."],["Trên sàn, bạn thường thấy số lượng ghi bằng BTC với nhiều chữ số thập phân, còn một số ví Bitcoin và mạng Lightning hiển thị trực tiếp bằng sats. ",["Phí mạng","gas-fee"]," Bitcoin cũng hay được tính theo sats trên mỗi vbyte (sat/vB), tức là phí phụ thuộc vào kích thước giao dịch chứ không phải số tiền bạn gửi."],"Hiểu satoshi giúp bạn bớt áp lực tâm lý khi thấy giá 1 BTC rất cao. Bạn có thể mua định kỳ một lượng sats nhỏ mỗi tuần hoặc mỗi tháng. Lưu ý các sàn có mức mua tối thiểu và mức rút tối thiểu riêng."],"example":["Giả sử BTC ở mức 40.000 ",["USDT","usdt"],". Khi đó 1 USDT mua được 1 / 40.000 = 0,000025 BTC, tức 2.500 sats. Nếu bạn mua 10 USDT mỗi tuần trong 8 tuần với cùng mức giá, bạn có 80 USDT, tương đương 200.000 sats hay 0,002 BTC. Nếu một giao dịch rút có kích thước 140 vbyte và phí là 5 sat/vB, phí mạng là 700 sats."],"mistakes":["Đếm sai số chữ số 0 khi đổi giữa BTC và sats, dẫn đến nhập sai số lượng khi chuyển.","Rút một lượng sats quá nhỏ về ví, để rồi phí mạng chiếm phần lớn số tiền.","Nghĩ rằng satoshi là một đồng coin riêng, trong khi nó chỉ là đơn vị đo của BTC."],"faq":[{"q":"1 BTC bằng bao nhiêu satoshi?","a":"1 BTC bằng 100.000.000 satoshi, và 1 satoshi bằng 0,00000001 BTC. Đây là quy tắc cố định của giao thức Bitcoin."},{"q":"Có mua được satoshi trên sàn không?","a":"Có, khi bạn mua một phần nhỏ BTC là bạn đang mua satoshi. Sàn thường hiển thị số lượng bằng BTC, còn nhiều ví hiển thị bằng sats."}],"title":"Satoshi (sats) là gì? 1 BTC bằng bao nhiêu sats","description":"Satoshi là đơn vị nhỏ nhất của Bitcoin. Tìm hiểu cách quy đổi BTC sang sats và vì sao phí mạng tính bằng sat/vB.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng."],["dollar-cost-averaging","DCA (Trung bình giá)","DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["cryptocurrency","Tiền mã hóa (Cryptocurrency)","Tiền mã hóa (cryptocurrency) là tài sản số được ghi nhận trên blockchain, chuyển trực tiếp giữa các ví mà không cần ngân hàng trung gian, và quyền sở hữu được bảo vệ bằng khóa riêng tư."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Một bitcoin đắt như vậy. Tôi vẫn có thể mua một phần chứ?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"fomo":{"slug":"fomo","cat":"basics","en":"FOMO","contentLocale":"vi","term":"FOMO (sợ bỏ lỡ)","aka":["FOMO","fear of missing out","sợ bỏ lỡ","fomo mua đuổi"],"short":"FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao.","body":[["FOMO xuất hiện khi bạn thấy giá tăng mạnh, bạn bè khoe lãi và mạng xã hội tràn ngập tin tốt. Cảm giác người khác đang giàu lên còn mình đứng ngoài đẩy bạn vào lệnh nhanh, thường bằng ",["lệnh thị trường","market-order"],", đôi khi với ",["đòn bẩy","leverage"],"."],"Vấn đề là khi FOMO lan rộng, phần lớn người mua đã vào rồi. Lực mua cạn dần, và chỉ cần một tin xấu nhỏ là giá điều chỉnh mạnh. Người mua cuối thường chịu lỗ nặng nhất.",["Cách chống FOMO đơn giản nhưng cần kỷ luật: viết ra lý do mua, mức giá vào, điểm ",["cắt lỗ","stop-loss"]," và số tiền tối đa trước khi đặt lệnh. Nếu bạn không thể trả lời các câu đó, hãy chờ. Chia nhỏ lệnh mua cũng giúp giảm áp lực phải vào đúng đỉnh."]],"example":["Một token tăng từ 1 lên 2,5 ",["USDT","usdt"]," trong 3 ngày. Bạn mua 2.000 USDT ở 2,4 USDT vì sợ lỡ, nhận khoảng 833 token. Hai ngày sau giá điều chỉnh về 1,6 USDT, phần của bạn còn khoảng 1.333 USDT, lỗ 667 USDT hay 33%. Nếu bạn đã giới hạn mỗi lệnh ở 2% tài khoản 10.000 USDT, tức chấp nhận rủi ro 200 USDT, và đặt cắt lỗ ở 2,16 USDT (dưới giá vào 10%), khoản vào lệnh hợp lý chỉ là 2.000 USDT và mức lỗ khi chạm cắt lỗ là 200 USDT."],"mistakes":["Mua bằng lệnh thị trường lúc giá đang tăng thẳng đứng, chịu trượt giá cao.","Bỏ qua kế hoạch cắt lỗ vì tin rằng giá sẽ còn tăng.","Tăng kích thước lệnh sau khi lỡ một đợt tăng để gỡ lại cơ hội đã mất."],"faq":[{"q":"FOMO trong crypto nghĩa là gì?","a":"FOMO là tâm lý sợ bỏ lỡ cơ hội kiếm lời, khiến bạn mua vội khi giá đang tăng nóng. Trong cộng đồng Việt, người ta hay nói fomo mua đuổi."},{"q":"Làm sao kiểm soát FOMO?","a":"Lập kế hoạch giao dịch trước, giới hạn rủi ro mỗi lệnh và chấp nhận rằng bạn sẽ không bắt được mọi đợt tăng. Tắt bớt các nhóm hô hào cũng giúp ích."}],"title":"FOMO là gì? Ý nghĩa FOMO trong crypto","description":"FOMO là gì, vì sao tâm lý sợ bỏ lỡ khiến bạn mua ở đỉnh và cách dùng kế hoạch giao dịch để kiểm soát nó.","related":[["fud","FUD (sợ hãi, bất an, nghi ngờ)","FUD (Fear, Uncertainty, Doubt) là thông tin hoặc tâm lý gây sợ hãi, bất an và nghi ngờ về một dự án hay thị trường, có thể đúng sự thật hoặc bị phóng đại để làm giá giảm."],["bull-market","Thị trường tăng giá (Bull market)","Thị trường tăng giá (bull market) là giai đoạn giá tài sản đi lên kéo dài, đi kèm tâm lý lạc quan, khối lượng giao dịch tăng và dòng tiền mới đổ vào thị trường."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."],["fear-and-greed-index","Chỉ số Sợ hãi và Tham lam (Fear and Greed Index)","Chỉ số Sợ hãi và Tham lam là thang điểm từ 0 đến 100 tóm tắt tâm lý thị trường crypto, trong đó điểm thấp thể hiện sợ hãi và điểm cao thể hiện tham lam."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Xác định mức có thể mất trước khi quyết định mua bao nhiêu"},"coin":null,"tool":null,"cta":false},"wash-trading":{"slug":"wash-trading","cat":"trading","en":"Wash trading","contentLocale":"vi","term":"Wash trading (giao dịch giả)","aka":["giao dịch tự khớp","volume ảo","giao dịch rửa"],"short":"Wash trading là việc một người hoặc một nhóm tự mua và tự bán cùng một tài sản với chính mình để tạo ra khối lượng giao dịch giả, khiến thị trường trông sôi động hơn thực tế.","body":["Người làm wash trading đặt lệnh mua và lệnh bán khớp với nhau từ các tài khoản họ kiểm soát. Tài sản không thực sự đổi chủ, nhưng volume trên sàn tăng lên. Mục đích thường là làm coin trông hấp dẫn, đẩy thứ hạng của sàn trên các trang tổng hợp, hoặc thu hút người mua thật.","Ở thị trường chứng khoán truyền thống, wash trading bị cấm. Trong crypto, mức độ quản lý khác nhau theo quốc gia, nhưng hành vi này đều làm sai lệch dữ liệu mà nhà đầu tư dựa vào.",["Dấu hiệu ",["nghi ngờ","fud"]," gồm: volume rất lớn nhưng ",["sổ lệnh","order-book"]," mỏng, volume tăng đều đặn bất thường, hay volume của một coin ở một sàn nhỏ cao hơn hẳn các sàn lớn. Trên ",["NFT","nft"]," và ",["DEX","dex"],", dữ liệu on-chain giúp phát hiện ví nào mua bán qua lại với nhau."]],"example":["Giả sử một token mới báo volume 24h là 40 triệu ",["USDT","usdt"],". Bạn mở sổ lệnh và thấy trong phạm vi 2% quanh giá chỉ có khoảng 50.000 USDT lệnh chờ mỗi bên. Tỷ lệ volume trên độ sâu là 40.000.000 / 100.000 = 400 lần, cao bất thường so với một cặp lớn. Đây là tín hiệu để bạn nghi ngờ phần lớn volume có thể đến từ giao dịch giả."],"mistakes":["Chọn coin chỉ vì volume lớn mà không kiểm tra độ sâu sổ lệnh.","Tin rằng NFT bán giá cao đồng nghĩa có người mua thật, trong khi người bán có thể tự mua lại.","Bỏ qua việc volume chỉ tập trung ở một sàn ít tên tuổi."],"faq":[{"q":"Làm sao nhận biết wash trading?","a":"So sánh volume với độ sâu sổ lệnh, đối chiếu volume giữa nhiều sàn và xem lịch sử giao dịch có lặp lại cùng khối lượng hay không."},{"q":"Wash trading có phạm pháp không?","a":"Ở nhiều thị trường tài chính, đây là hành vi thao túng bị cấm. Với crypto, quy định cụ thể khác nhau theo từng quốc gia."}],"title":"Wash trading là gì? Cách nhận biết volume ảo","description":"Wash trading là gì, vì sao sàn và dự án tạo volume ảo, và các dấu hiệu giúp bạn nhận ra khối lượng giao dịch giả.","related":[["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra."],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá."]],"lesson":null,"coin":null,"tool":"/exchanges","cta":false},"whale":{"slug":"whale","cat":"trading","en":"Whale","contentLocale":"vi","term":"Cá voi (Whale)","aka":["whale","cá mập","ví cá voi"],"short":"Cá voi (whale) là cá nhân hoặc tổ chức nắm giữ lượng lớn một loại tiền mã hóa, đủ để các giao dịch của họ có thể ảnh hưởng tới giá hoặc thanh khoản.","body":[["Không có ngưỡng chính thức để gọi là cá voi. Với ",["BTC","bitcoin"],", nhiều công cụ ",["phân tích on-chain","on-chain-analysis"]," xếp ví giữ từ 1.000 BTC trở lên vào nhóm này; với coin nhỏ, vài phần trăm nguồn cung đã là rất lớn. Ví cá voi có thể là quỹ, sàn giao dịch, dự án hoặc người nắm giữ từ sớm."],["Người giao dịch theo dõi cá voi vì một lệnh bán lớn đưa ",["lên sàn","token-listing"]," có thể gây áp lực giá, đặc biệt ở coin ",["thanh khoản","liquidity"]," thấp. Các công cụ cảnh báo giao dịch lớn và dữ liệu ",["dòng tiền vào ra sàn","exchange-netflow"]," giúp quan sát hành vi này."],["Cần thận trọng khi diễn giải: một khoản chuyển lớn có thể chỉ là sàn đổi ",["ví lạnh","cold-wallet"]," nội bộ, không phải lệnh bán. Ví được gắn nhãn sai cũng là chuyện thường gặp."]],"example":"Giả sử một token có tổng cung 100 triệu, và một ví giữ 8 triệu token. Sổ lệnh trên sàn chỉ có khoảng 400.000 USDT lệnh mua trong phạm vi 5% quanh giá 0,5 USDT, tương đương 800.000 token. Nếu ví này bán 2 triệu token (1 triệu USDT) bằng lệnh thị trường, lệnh sẽ ăn qua toàn bộ vùng 5% và đẩy giá xuống sâu hơn.","mistakes":["Coi mọi khoản chuyển lớn lên sàn là tín hiệu bán.","Mua theo cá voi mà không biết ví đó thuộc về ai.","Bỏ qua mức độ tập trung nguồn cung khi chọn coin nhỏ."],"faq":[{"q":"Cá voi trong crypto là gì?","a":"Là người hoặc tổ chức nắm lượng lớn một coin, đủ để giao dịch của họ ảnh hưởng tới giá. Không có ngưỡng chính thức chung cho mọi coin."},{"q":"Làm sao theo dõi ví cá voi?","a":"Bạn có thể dùng trình khám phá blockchain và các công cụ phân tích on-chain để xem số dư, giao dịch lớn và dòng tiền vào ra sàn."}],"title":"Cá voi (whale) là gì trong crypto? Cách theo dõi","description":"Cá voi crypto là ai, vì sao giao dịch của họ ảnh hưởng tới giá và cách đọc dữ liệu ví lớn mà không diễn giải sai.","related":[["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."],["exchange-netflow","Dòng tiền vào ra sàn (exchange netflow)","Dòng tiền vào ra sàn là chỉ số on-chain đo lượng coin chuyển vào ví sàn trừ đi lượng coin rút ra khỏi sàn trong một khoảng thời gian."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"margin-call":{"slug":"margin-call","cat":"derivatives","en":"Margin call","contentLocale":"vi","term":"Margin call (Cảnh báo ký quỹ)","aka":["margin call","cảnh báo ký quỹ","gọi ký quỹ"],"short":"Margin call là cảnh báo từ sàn khi ký quỹ của bạn giảm gần mức ký quỹ duy trì, yêu cầu bạn nạp thêm ký quỹ hoặc giảm vị thế để tránh bị thanh lý.","body":[["Trong tài chính truyền thống, margin call là yêu cầu nộp thêm tiền trong một thời hạn. Trong crypto, thị trường chạy 24/7 nên sàn thường chỉ gửi thông báo qua ứng dụng, email hoặc SMS khi tỷ lệ ký quỹ chạm một ngưỡng cảnh báo. Không có thời gian ân hạn: nếu giá tiếp tục đi ngược, ",["thanh lý","liquidation"]," có thể diễn ra ngay."],"Khi nhận cảnh báo, bạn có ba lựa chọn: thêm ký quỹ, đóng bớt vị thế, hoặc đóng hẳn và chấp nhận lỗ. Thêm ký quỹ vào một vị thế đang sai hướng chỉ nên làm khi kế hoạch giao dịch vẫn còn hợp lý.","Ngưỡng cảnh báo và cách gửi thông báo khác nhau giữa các sàn. Hãy bật thông báo và đừng coi margin call là lưới an toàn."],"example":["Giả sử vị thế của bạn có ",["ký quỹ duy trì","maintenance-margin"]," 400 ",["USDT","usdt"]," và sàn cảnh báo khi số dư ký quỹ còn 1,5 lần mức đó, tức 600 USDT. Ban đầu bạn có 2.000 USDT ký quỹ. Thị trường giảm mạnh và bạn lỗ 1.400 USDT, số dư còn 600 USDT, sàn gửi margin call. Nếu giá đi tiếp và bạn lỗ thêm 200 USDT trước khi kịp phản ứng, vị thế bị thanh lý."],"mistakes":["Chờ margin call mới hành động thay vì đặt cắt lỗ từ đầu.","Nạp thêm tiền liên tục để cứu một vị thế sai hướng.","Tắt thông báo của ứng dụng sàn khi đang giữ vị thế có đòn bẩy."],"faq":[{"q":"Margin call trong crypto là gì?","a":"Là cảnh báo rằng ký quỹ sắp không đủ để giữ vị thế. Nếu không xử lý và giá đi tiếp, vị thế sẽ bị thanh lý."},{"q":"Có thời gian để nạp tiền sau margin call không?","a":"Thường là không có thời hạn cố định. Thanh lý có thể xảy ra bất cứ lúc nào khi ký quỹ chạm mức duy trì."}],"title":"Margin call là gì? Cảnh báo ký quỹ trong crypto","description":"Margin call là gì, khi nào sàn gửi cảnh báo ký quỹ và bạn nên làm gì trước khi vị thế bị thanh lý.","related":[["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ về không?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation":{"slug":"liquidation","cat":"derivatives","en":"Liquidation","contentLocale":"vi","term":"Thanh lý (Liquidation)","aka":["liquidation","cháy tài khoản","bị thanh lý","cháy"],"short":"Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì.","body":[["Sàn theo dõi ",["giá đánh dấu (mark price)","mark-price"],". Khi lỗ chưa thực hiện làm số dư ký quỹ của vị thế giảm xuống mức ",["ký quỹ duy trì","maintenance-margin"],", công cụ thanh lý tiếp quản và đóng vị thế. Với ",["ký quỹ cô lập","isolated-margin"],", bạn mất phần ký quỹ của vị thế đó; với ",["ký quỹ chéo","cross-margin"],", có thể mất phần lớn tài khoản."],["Nhiều sàn thanh lý từng phần trước, giảm khối lượng để đưa vị thế về mức an toàn, rồi mới đóng hết nếu cần. Một khoản phí thanh lý có thể được thu và chuyển vào ",["quỹ bảo hiểm","insurance-fund"],". Nếu vị thế được đóng ở giá tệ hơn giá phá sản, quỹ bảo hiểm bù phần thiếu; nếu quỹ không đủ, sàn có thể dùng cơ chế ",["giảm đòn bẩy tự động (ADL)","auto-deleveraging"],"."],"Thanh lý hàng loạt có thể tạo hiệu ứng dây chuyền: lệnh đóng bắt buộc đẩy giá đi xa hơn, kéo thêm các vị thế khác bị cháy."],"example":"Giả sử bạn long 0,5 BTC ở 64.000 USDT với ký quỹ cô lập 3.200 USDT (10x), giá trị vị thế 32.000 USDT. Ký quỹ duy trì 0,5% là 160 USDT. Vị thế bị thanh lý khi lỗ đạt 3.040 USDT, tức khi giá đánh dấu giảm 3.040 / 0,5 = 6.080 USDT, xuống khoảng 57.920 USDT. Bạn mất toàn bộ khoản ký quỹ đã gán, cộng phí.","mistakes":["Không đặt cắt lỗ và để sàn thanh lý thay mình.","Nghĩ rằng chỉ bị thanh lý khi giá giao dịch cuối chạm giá thanh lý, trong khi sàn dùng giá đánh dấu.","Dùng ký quỹ chéo với đòn bẩy cao mà không biết cả tài khoản có thể bị cuốn theo."],"faq":[{"q":"Cháy tài khoản là gì?","a":"Là cách gọi thông dụng của thanh lý: sàn đóng vị thế của bạn vì ký quỹ không đủ. Bạn mất phần ký quỹ của vị thế, hoặc nhiều hơn nếu dùng ký quỹ chéo."},{"q":"Làm sao tránh bị thanh lý?","a":"Dùng đòn bẩy thấp, tính khối lượng theo cắt lỗ và đặt cắt lỗ trước giá thanh lý. Theo dõi tỷ lệ ký quỹ khi thị trường biến động mạnh."}],"title":"Thanh lý (cháy tài khoản) là gì trong crypto?","description":"Thanh lý là gì, vì sao vị thế đòn bẩy bị cháy, cách sàn dùng giá đánh dấu và quỹ bảo hiểm, và cách tránh bị thanh lý.","related":[["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["insurance-fund","Quỹ bảo hiểm (Insurance fund)","Quỹ bảo hiểm là khoản dự trữ của sàn dùng để bù phần lỗ khi một vị thế bị thanh lý ở giá tệ hơn giá phá sản, nhằm tránh chuyển khoản lỗ đó sang người giao dịch khác."],["auto-deleveraging","Giảm đòn bẩy tự động (ADL)","Giảm đòn bẩy tự động (ADL) là cơ chế cuối cùng của sàn: khi quỹ bảo hiểm không đủ bù lỗ từ một vị thế bị thanh lý, sàn tự đóng một phần vị thế đang lãi ở phía đối diện."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation-price":{"slug":"liquidation-price","cat":"derivatives","en":"Liquidation price","contentLocale":"vi","term":"Giá thanh lý (Liquidation price)","aka":["liquidation price","giá cháy","giá thanh lý ước tính"],"short":"Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ.","body":[["Sàn hiển thị giá thanh lý ước tính ngay khi bạn mở vị thế. Nó phụ thuộc vào giá vào lệnh, ",["đòn bẩy","leverage"],", ký quỹ thực tế, tỷ lệ ",["ký quỹ duy trì","maintenance-margin"]," và phí. Đòn bẩy càng cao, giá thanh lý càng gần giá vào lệnh."],"Ở chế độ cô lập, giá thanh lý khá ổn định trừ khi bạn thêm hoặc rút ký quỹ. Ở chế độ chéo, giá thanh lý thay đổi liên tục theo số dư tài khoản và lãi lỗ của các vị thế khác. Funding phải trả cũng làm ký quỹ giảm và kéo giá thanh lý lại gần.","Công thức chính xác khác nhau theo sàn và loại hợp đồng, vì vậy hãy dùng con số trên ứng dụng thay vì tự tính rồi coi là chính xác."],"example":["Giả sử bạn short 10 AVAX ở 30 ",["USDT","usdt"]," với ",["ký quỹ cô lập","isolated-margin"]," 60 USDT (5x), giá trị vị thế 300 USDT. Ký quỹ duy trì 1% là 3 USDT. Vị thế ",["bị thanh lý","liquidation"]," khi lỗ đạt 57 USDT, tức giá tăng 5,7 USDT mỗi AVAX, lên khoảng 35,7 USDT. Nếu dùng 20x với ký quỹ 15 USDT, giá chỉ cần tăng khoảng 1,2 USDT, lên khoảng 31,2 USDT, là đã cháy."],"mistakes":["Đặt cắt lỗ xa hơn giá thanh lý, khiến cắt lỗ không bao giờ được kích hoạt.","Quên rằng giá thanh lý ở ký quỹ chéo thay đổi theo các vị thế khác.","Coi giá thanh lý trên ứng dụng là cố định trong khi funding và phí làm nó dịch chuyển."],"faq":[{"q":"Giá thanh lý được tính thế nào?","a":"Dựa trên giá vào lệnh, ký quỹ, đòn bẩy và tỷ lệ ký quỹ duy trì. Mỗi sàn có công thức riêng, nên hãy xem giá ước tính trên ứng dụng."},{"q":"Làm sao đẩy giá thanh lý ra xa?","a":"Thêm ký quỹ vào vị thế cô lập, giảm khối lượng hoặc giảm đòn bẩy. Điều này cho vị thế nhiều không gian hơn trước khi bị đóng."}],"title":"Giá thanh lý là gì? Cách tính giá cháy vị thế","description":"Giá thanh lý là gì, đòn bẩy và ký quỹ ảnh hưởng ra sao, và vì sao cắt lỗ phải nằm trước giá thanh lý.","related":[["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/liquidations","cta":false},"long-short-ratio":{"slug":"long-short-ratio","cat":"derivatives","en":"Long/short ratio","contentLocale":"vi","term":"Tỷ lệ Long/Short (Long/short ratio)","aka":["long short ratio","tỷ lệ long short","L/S ratio"],"short":"Tỷ lệ long/short là chỉ số so sánh số tài khoản hoặc khối lượng vị thế đang long với số đang short trên một sàn, dùng để đọc tâm lý người giao dịch phái sinh.","body":[["Sàn thường công bố vài phiên bản: tỷ lệ theo số tài khoản (bao nhiêu tài khoản đang long so với short), tỷ lệ của nhóm tài khoản lớn, và tỷ lệ theo ",["khối lượng vị thế","position-sizing"],". Tỷ lệ 1,5 nghĩa là phía long nhiều gấp 1,5 lần phía short theo cách đo đó."],"Cần nhớ rằng tổng hợp đồng long luôn bằng tổng hợp đồng short trên toàn thị trường. Tỷ lệ theo tài khoản chỉ cho biết có nhiều người nhỏ đứng một phía, trong khi phía kia có thể là ít tài khoản lớn hơn.",["Tỷ lệ cực đoan đôi khi đi trước các cú quét ",["thanh lý","liquidation"]," ngược chiều đám đông, nhưng không phải tín hiệu đáng tin một mình. Hãy xem cùng ",["funding rate","funding-rate"]," và open interest."]],"example":["Giả sử trên một sàn có 6.000 tài khoản đang long ",["BTC","bitcoin"]," và 4.000 tài khoản đang short. Tỷ lệ long/short theo tài khoản là 6.000 / 4.000 = 1,5, tức 60% tài khoản long. Nhưng nếu 4.000 tài khoản short giữ trung bình 2 BTC còn 6.000 tài khoản long giữ trung bình 1,33 BTC, tổng khối lượng hai bên đều khoảng 8.000 BTC."],"mistakes":["Nghĩ rằng tỷ lệ long cao nghĩa là có nhiều tiền đặt vào phe long hơn.","So sánh tỷ lệ giữa các sàn mà không biết mỗi sàn đo theo cách nào.","Giao dịch ngược đám đông chỉ dựa vào tỷ lệ này."],"faq":[{"q":"Long short ratio cao có nghĩa là gì?","a":"Nghĩa là nhiều tài khoản đang long hơn short theo cách sàn đo. Nó phản ánh tâm lý, không phải dự báo giá."},{"q":"Vì sao tổng long luôn bằng tổng short mà tỷ lệ vẫn khác 1?","a":"Vì tỷ lệ thường đếm số tài khoản, không đếm khối lượng. Ít tài khoản lớn có thể cân với nhiều tài khoản nhỏ."}],"title":"Tỷ lệ long/short là gì? Cách đọc long short ratio","description":"Tỷ lệ long/short là gì, các cách sàn đo chỉ số này và vì sao không nên dùng nó làm tín hiệu giao dịch duy nhất.","related":[["open-interest","Hợp đồng mở (Open interest)","Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["long-and-short","Long và Short (Vị thế mua và bán)","Long là mở vị thế kiếm lời khi giá tăng, short là mở vị thế kiếm lời khi giá giảm; hai thuật ngữ này dùng phổ biến trong giao dịch hợp đồng tương lai và ký quỹ."],["short-squeeze","Short squeeze (Ép short)","Short squeeze là hiện tượng giá tăng nhanh buộc nhiều người đang short phải đóng vị thế hoặc bị thanh lý, và lệnh mua bắt buộc của họ lại đẩy giá tăng tiếp."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"anti-phishing-code":{"slug":"anti-phishing-code","cat":"wallets-security","en":"Anti-phishing code","contentLocale":"vi","term":"Mã chống lừa đảo (Anti-phishing code)","aka":["anti-phishing code","mã anti-phishing","mã chống phishing"],"short":"Mã chống lừa đảo là chuỗi ký tự riêng bạn tự đặt trên sàn, sau đó sàn chèn nó vào mọi email chính thức để bạn phân biệt email thật với email giả mạo.","body":["Kẻ lừa đảo có thể sao chép logo, giao diện và giọng văn email của sàn rất giống thật, thậm chí dùng tên miền gần giống. Nhưng chúng không biết mã bí mật bạn đã đặt trong phần cài đặt bảo mật. Email nào không có mã đó, hoặc có mã sai, thì coi như giả.","Nhiều sàn lớn như Binance, OKX, Bybit, Bitget cung cấp tính năng này; một số sàn còn hiển thị mã trong tin nhắn hệ thống hoặc SMS. Tên gọi và phạm vi áp dụng có thể khác nhau, hãy xem trang bảo mật của sàn bạn dùng.",["Mã chống lừa đảo chỉ giúp nhận diện email. Nó không thay thế ",["2FA","two-factor-authentication"]," và không bảo vệ bạn nếu bạn tự gõ thông tin đăng nhập vào trang giả."]],"example":["Giả sử bạn đặt mã chống lừa đảo là “meoden2024”. Một tối bạn nhận email báo “Tài khoản bị khóa, xác minh trong 24 giờ để tránh mất 1.200 ",["USDT","usdt"],"”, kèm nút đăng nhập. Email có logo đúng nhưng không có dòng meoden2024. Bạn bỏ qua email, tự mở ứng dụng sàn và thấy tài khoản hoàn toàn bình thường."],"mistakes":["Đặt mã quá dễ đoán như tên sàn hoặc 123456.","Chia sẻ ảnh chụp email có mã chống lừa đảo lên nhóm chat công khai.","Tin rằng email có mã đúng thì mọi đường link trong đó luôn an toàn mà không kiểm tra tên miền."],"faq":[{"q":"Mã chống lừa đảo nằm ở đâu trên sàn?","a":"Thường trong mục Bảo mật hoặc Cài đặt tài khoản. Sau khi đặt, mã sẽ xuất hiện trong email chính thức của sàn."},{"q":"Email không có mã chống lừa đảo thì sao?","a":"Nếu bạn đã bật tính năng mà email lại không có mã, hãy coi đó là email giả và đừng bấm vào bất kỳ link nào."}],"title":"Mã chống lừa đảo (anti-phishing code) là gì?","description":"Mã chống lừa đảo là gì, cách bật trên sàn crypto và dùng nó để nhận ra email giả mạo trước khi bấm vào link.","related":[["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["two-factor-authentication","Xác thực hai yếu tố (2FA)","Xác thực hai yếu tố (2FA) là lớp bảo mật yêu cầu thêm một mã hoặc thiết bị ngoài mật khẩu khi đăng nhập, rút tiền hay đổi cài đặt, để kẻ chỉ có mật khẩu vẫn không vào được tài khoản."],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":null,"cta":false},"pig-butchering-scam":{"slug":"pig-butchering-scam","cat":"wallets-security","en":"Pig-butchering scam","contentLocale":"vi","term":"Lừa đảo “nuôi heo” (Pig-butchering scam)","aka":["pig butchering","lừa đảo tình cảm","lừa đảo đầu tư qua mạng"],"short":"Lừa đảo “nuôi heo” là chiêu lừa kéo dài, kẻ gian làm quen, xây dựng lòng tin hoặc tình cảm qua mạng rồi dẫn nạn nhân vào nền tảng đầu tư crypto giả để rút sạch tiền.","body":[["Kịch bản thường bắt đầu bằng một tin nhắn “nhầm số”, một người quen trên ứng dụng hẹn hò hoặc nhóm đầu tư. Sau nhiều tuần trò chuyện thân thiết, họ khoe lợi nhuận và hướng dẫn bạn mua ",["USDT","usdt"],", rồi chuyển sang một sàn hoặc app do họ kiểm soát."],"Trên nền tảng giả, số dư tăng đều đặn và bạn có thể được rút một khoản nhỏ để tin tưởng. Khi bạn nạp số tiền lớn, việc rút bị chặn với lý do “nộp thuế”, “phí xác minh” hay “phí mở khóa”. Nạp thêm cũng không bao giờ rút được.","Dấu hiệu cần dừng lại: người chỉ quen qua mạng nói về đầu tư, nền tảng không có trên các trang so sánh hay cửa hàng ứng dụng uy tín, lợi nhuận đều đặn bất thường, và yêu cầu nộp thêm tiền để rút."],"example":"Giả sử một người quen qua mạng hướng dẫn bạn nạp 1.000 USDT vào app “sàn quốc tế”. Sau hai tuần, app báo lãi 30%, bạn rút thử 200 USDT và nhận được thật. Bạn nạp thêm 10.000 USDT, số dư hiện 14.000 USDT. Khi rút, app yêu cầu nộp 20% “thuế”, tức 2.800 USDT. Đây là dấu hiệu điển hình: số dư chỉ là con số trên màn hình, và nộp thêm chỉ làm mất thêm.","mistakes":["Tin rằng rút được một khoản nhỏ chứng tỏ nền tảng là thật.","Nộp thêm “phí” hoặc “thuế” để mở khóa số dư bị chặn.","Cài app đầu tư từ đường link người lạ gửi thay vì cửa hàng ứng dụng chính thức."],"faq":[{"q":"Vì sao gọi là “nuôi heo”?","a":"Tên gọi xuất phát từ cách kẻ gian “vỗ béo” nạn nhân bằng sự tin tưởng và lợi nhuận giả trong thời gian dài trước khi lấy toàn bộ tiền."},{"q":"Bị lừa thì nên làm gì?","a":"Dừng chuyển tiền ngay, lưu lại tin nhắn, địa chỉ ví, mã giao dịch và báo cơ quan công an cùng sàn nơi bạn đã rút USDT. Cảnh giác với người hứa “lấy lại tiền” có thu phí, vì đó thường là lừa đảo lần hai."}],"title":"Lừa đảo nuôi heo (pig butchering) là gì?","description":"Lừa đảo pig butchering là gì, kịch bản làm quen rồi dụ đầu tư crypto giả, dấu hiệu nhận biết và cách xử lý nếu bị lừa.","related":[["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0."],["p2p-trading","Giao dịch P2P (C2C)","Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã."},"coin":null,"tool":null,"cta":false},"hash-rate":{"slug":"hash-rate","cat":"onchain","en":"Hash rate","contentLocale":"vi","term":"Hash rate (tốc độ băm)","aka":["hashrate","tỷ lệ băm","sức mạnh băm"],"short":"Hash rate là tổng sức mạnh tính toán mà các máy đào dùng để bảo vệ một blockchain proof of work, đo bằng số phép băm mỗi giây.","body":[["Trong ",["Bitcoin","bitcoin"],", thợ đào liên tục thử các con số để tìm ra một mã băm đạt yêu cầu và giành quyền tạo khối mới. Mỗi lần thử là một phép băm. Toàn mạng Bitcoin hiện thực hiện hàng trăm exahash mỗi giây, tức hàng trăm tỷ tỷ phép băm."],"Hash rate càng cao thì việc tấn công mạng, ví dụ tấn công 51%, càng tốn kém. Mạng tự điều chỉnh độ khó khoảng mỗi 2.016 khối để thời gian tạo khối trung bình vẫn quanh 10 phút, dù hash rate tăng hay giảm.","Nhiều người theo dõi hash rate như thước đo sức khỏe của ngành đào. Sau các kỳ halving, như tháng 4 năm 2024 khi phần thưởng khối giảm còn 3,125 BTC, thợ đào có chi phí cao có thể tắt máy, khiến hash rate chững lại một thời gian. Tuy vậy, hash rate không phải tín hiệu giá trực tiếp."],"example":"Giả sử toàn mạng có hash rate 600 EH/s và bạn vận hành máy đào 200 TH/s. Vì 1 EH/s bằng 1.000.000 TH/s, phần của bạn là 200 chia 600.000.000, khoảng 0,000033%. Mỗi ngày có khoảng 144 khối, mỗi khối thưởng 3,125 BTC, tổng khoảng 450 BTC. Về lý thuyết, phần trung bình của bạn khoảng 0,00015 BTC mỗi ngày, chưa tính phí giao dịch, phí pool và tiền điện.","mistakes":["Nghĩ hash rate tăng thì giá Bitcoin chắc chắn tăng theo.","Nhầm hash rate với tốc độ xử lý giao dịch của mạng.","Tính lợi nhuận đào mà bỏ qua việc độ khó tăng dần theo thời gian."],"faq":[{"q":"Hash rate giảm có nguy hiểm không?","a":"Giảm ngắn hạn thường không nguy hiểm, vì độ khó sẽ tự điều chỉnh. Hash rate giảm mạnh và kéo dài thì mạng dễ bị tấn công hơn về lý thuyết."},{"q":"Ethereum còn hash rate không?","a":"Không. Từ The Merge vào tháng 9 năm 2022, Ethereum chuyển sang proof of stake nên không còn đào bằng sức mạnh băm."}],"title":"Hash rate là gì? Tốc độ băm trong đào Bitcoin","description":"Hash rate đo sức mạnh tính toán bảo vệ mạng proof of work. Tìm hiểu đơn vị, độ khó, halving và cách tính phần đào.","related":[["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng."],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["bitcoin-halving","Bitcoin halving (sự kiện giảm một nửa)","Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới."],["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"exchange-netflow":{"slug":"exchange-netflow","cat":"onchain","en":"Exchange inflows and outflows","contentLocale":"vi","term":"Dòng tiền vào ra sàn (exchange netflow)","aka":["exchange netflow","netflow","inflow outflow sàn","dòng tiền ròng sàn"],"short":"Dòng tiền vào ra sàn là chỉ số on-chain đo lượng coin chuyển vào ví sàn trừ đi lượng coin rút ra khỏi sàn trong một khoảng thời gian.","body":[["Inflow là lượng coin gửi ",["lên sàn","token-listing"],", outflow là lượng coin rút khỏi sàn, netflow là chênh lệch giữa hai con số. Netflow dương nghĩa là coin đang dồn lên sàn, netflow âm nghĩa là coin rời sàn."],["Cách hiểu phổ biến: coin lên sàn thường để bán hoặc dùng làm ký quỹ, còn coin rời sàn thường để cất giữ lâu dài. Với ",["stablecoin","stablecoin"]," thì ngược lại, stablecoin chảy vào sàn có thể là tiền chuẩn bị mua."],["Chỉ số này dựa vào việc nhận diện ví của sàn, mà việc gắn nhãn không bao giờ hoàn hảo. Sàn chuyển ví nội bộ, nâng cấp ",["ví lạnh","cold-wallet"]," hay xử lý quỹ ETF đều có thể tạo ra những con số lớn bất thường. Hãy kiểm tra nguyên nhân trước khi đọc tín hiệu."]],"example":["Giả sử một ngày có 12.000 ",["ETH","ethereum"]," chuyển vào các sàn và 9.000 ETH rút ra. Netflow là dương 3.000 ETH. Nếu ETH giá 2.500 USD, khoảng 7,5 triệu USD ETH vừa được đưa lên sàn. Đây có thể là áp lực bán tiềm năng. Nhưng nếu bạn thấy 2.800 ETH trong số đó đến từ một ví duy nhất của chính sàn đó, thì phần lớn chỉ là chuyển nội bộ, và tín hiệu yếu đi đáng kể."],"mistakes":["Đọc netflow một ngày rồi vội vàng mở vị thế theo.","Áp cùng cách hiểu cho BTC và stablecoin, trong khi ý nghĩa dòng chảy của hai loại là ngược nhau.","Bỏ qua các đợt chuyển ví nội bộ của sàn làm méo số liệu."],"faq":[{"q":"Netflow âm có phải tín hiệu tăng giá?","a":"Nhiều người coi đó là dấu hiệu tích lũy, nhưng không phải tín hiệu chắc chắn. Giá còn chịu tác động của phái sinh, tin tức và dòng tiền ngoài chuỗi."},{"q":"Dữ liệu netflow lấy từ đâu?","a":"Từ các nền tảng phân tích on-chain gắn nhãn ví sàn. Mỗi nền tảng có danh sách ví khác nhau nên con số có thể chênh lệch."}],"title":"Exchange netflow là gì? Dòng tiền vào ra sàn crypto","description":"Netflow đo lượng coin vào và ra khỏi sàn. Tìm hiểu cách đọc inflow, outflow, khác biệt với stablecoin và các bẫy dữ liệu.","related":[["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."],["whale","Cá voi (Whale)","Cá voi (whale) là cá nhân hoặc tổ chức nắm giữ lượng lớn một loại tiền mã hóa, đủ để các giao dịch của họ có thể ảnh hưởng tới giá hoặc thanh khoản."],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"active-addresses":{"slug":"active-addresses","cat":"onchain","en":"Active addresses","contentLocale":"vi","term":"Địa chỉ hoạt động (active addresses)","aka":["active addresses","số địa chỉ hoạt động","ví hoạt động"],"short":"Địa chỉ hoạt động là số địa chỉ ví riêng biệt có gửi hoặc nhận giao dịch thành công trên một blockchain trong một khoảng thời gian, thường là một ngày.","body":["Chỉ số này được dùng để ước lượng mức độ sử dụng thực tế của một mạng. Nếu số địa chỉ hoạt động tăng đều trong nhiều tháng, có thể mạng đang thu hút thêm người dùng hoặc ứng dụng mới.",["Tuy nhiên, một địa chỉ không bằng một người. Một người có thể dùng hàng chục ví, còn một ví sàn có thể đại diện cho hàng triệu khách hàng. Các chiến dịch ",["airdrop","airdrop"]," cũng thường làm số địa chỉ tăng vọt vì người săn airdrop tạo nhiều ví để tương tác."],["Vì vậy, nên đọc địa chỉ hoạt động cùng với phí giao dịch, khối lượng chuyển và ",["tổng giá trị khóa","total-value-locked"],". Một mạng có nhiều địa chỉ nhưng phí rất thấp và giá trị chuyển nhỏ có thể đang bị bot làm đẹp số liệu."]],"example":["Giả sử một ",["blockchain","blockchain"]," mới báo cáo số địa chỉ hoạt động tăng từ 50.000 lên 400.000 mỗi ngày chỉ trong hai tuần, đúng lúc dự án công bố chương trình điểm thưởng cho airdrop. Trong cùng giai đoạn, tổng ",["phí mạng","gas-fee"]," chỉ tăng từ 2.000 lên 3.000 USD mỗi ngày. Như vậy mỗi địa chỉ trả trung bình chưa tới 0,01 USD phí. Con số tăng gấp tám lần nhiều khả năng đến từ ví săn thưởng hơn là người dùng thật."],"mistakes":["Đánh đồng số địa chỉ hoạt động với số người dùng thật.","So sánh địa chỉ hoạt động giữa các chuỗi có phí rất khác nhau mà không điều chỉnh.","Không để ý các chiến dịch airdrop hay bot làm số liệu tăng đột biến."],"faq":[{"q":"Địa chỉ hoạt động tăng có tốt không?","a":"Thường là dấu hiệu mạng được sử dụng nhiều hơn, nhưng cần xem có phải do airdrop hay bot hay không. Hãy kết hợp với phí và giá trị chuyển để đánh giá."},{"q":"Địa chỉ mới và địa chỉ hoạt động khác nhau thế nào?","a":"Địa chỉ mới là ví lần đầu xuất hiện trên chuỗi. Địa chỉ hoạt động gồm cả ví cũ lẫn ví mới có giao dịch trong khoảng thời gian đó."}],"title":"Địa chỉ hoạt động là gì? Chỉ số active addresses","description":"Active addresses đo số ví có giao dịch trên blockchain. Hiểu cách đọc chỉ số, hạn chế do airdrop và bot, kèm ví dụ cụ thể.","related":[["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["total-value-locked","Tổng giá trị khóa (TVL)","TVL (tổng giá trị khóa) là tổng giá trị tài sản crypto đang được gửi trong một giao thức DeFi hoặc một blockchain, thường tính bằng USD, dùng để đo quy mô và mức độ sử dụng."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"fear-and-greed-index":{"slug":"fear-and-greed-index","cat":"onchain","en":"Fear and Greed Index","contentLocale":"vi","term":"Chỉ số Sợ hãi và Tham lam (Fear and Greed Index)","aka":["Fear and Greed Index","chỉ số tham lam sợ hãi","chỉ số F&G"],"short":"Chỉ số Sợ hãi và Tham lam là thang điểm từ 0 đến 100 tóm tắt tâm lý thị trường crypto, trong đó điểm thấp thể hiện sợ hãi và điểm cao thể hiện tham lam.","body":[["Chỉ số được tổng hợp từ nhiều nguồn dữ liệu, thường gồm ",["biến động giá","volatility"],", động lượng và ",["khối lượng giao dịch","trading-volume"],", mức độ thảo luận trên mạng xã hội, tỷ lệ thống trị của ",["Bitcoin","bitcoin"]," và xu hướng tìm kiếm. Mỗi nhà cung cấp có công thức và trọng số riêng, nên cùng một ngày các chỉ số có thể cho điểm khác nhau."],"Thang điểm thường được chia thành các vùng: sợ hãi tột độ, sợ hãi, trung lập, tham lam và tham lam tột độ. Nhiều người dùng chỉ số như một lời nhắc ngược chiều: khi đám đông quá hoảng loạn hoặc quá hưng phấn, giá thường biến động mạnh.","Chỉ số chỉ phản ánh tâm lý, không phải tín hiệu vào lệnh. Thị trường có thể ở vùng tham lam tột độ nhiều tuần liền mà giá vẫn tiếp tục tăng, hoặc ở vùng sợ hãi rất lâu trong một đợt giảm dài."],"example":["Giả sử BTC giảm từ 70.000 xuống 56.000 USD trong mười ngày, tức giảm 20%. ",["Funding rate","funding-rate"]," chuyển âm, mạng xã hội tràn ngập bài viết bi quan và chỉ số rơi xuống 15, vùng sợ hãi tột độ. Một nhà giao dịch không dùng con số này để mua dồn, mà chia số vốn dự định 1.000 USD thành bốn phần 250 USD, mua dần mỗi tuần. Cách này giúp tránh việc ",["đặt cược","staking"]," toàn bộ vào một ngày chỉ vì chỉ số thấp."],"mistakes":["Mua ngay khi chỉ số chạm vùng sợ hãi tột độ mà không có kế hoạch quản lý vốn.","Bán hết chỉ vì chỉ số ở vùng tham lam, trong khi xu hướng có thể còn kéo dài.","So sánh điểm của hai nhà cung cấp khác nhau như thể chúng dùng chung công thức."],"faq":[{"q":"Chỉ số Sợ hãi và Tham lam cập nhật bao lâu một lần?","a":"Phần lớn nhà cung cấp cập nhật mỗi ngày một lần. Một số trang có thêm dữ liệu trong ngày, hãy xem mô tả phương pháp của trang bạn dùng."},{"q":"Chỉ số thấp có nghĩa là nên mua?","a":"Không nhất thiết. Điểm thấp cho biết tâm lý đang sợ hãi, nhưng giá vẫn có thể giảm tiếp. Hãy dùng nó như một yếu tố bối cảnh bên cạnh kế hoạch vốn của bạn."}],"title":"Chỉ số Sợ hãi và Tham lam là gì? Cách đọc F&G","description":"Fear and Greed Index đo tâm lý thị trường crypto từ 0 đến 100. Tìm hiểu thành phần, cách đọc các vùng điểm và giới hạn.","related":[["fomo","FOMO (sợ bỏ lỡ)","FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao."],["fud","FUD (sợ hãi, bất an, nghi ngờ)","FUD (Fear, Uncertainty, Doubt) là thông tin hoặc tâm lý gây sợ hãi, bất an và nghi ngờ về một dự án hay thị trường, có thể đúng sự thật hoặc bị phóng đại để làm giá giảm."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"referral-code":{"slug":"referral-code","cat":"exchange-features","en":"Referral code (fee rebate)","contentLocale":"vi","term":"Mã giới thiệu (hoàn phí giao dịch)","aka":["mã giới thiệu","referral code","mã mời","ref code"],"short":"Mã giới thiệu là mã bạn nhập khi đăng ký sàn để liên kết tài khoản với người hoặc đối tác giới thiệu, thường giúp bạn được hoàn một phần phí giao dịch hoặc nhận ưu đãi người mới.","body":[["Mỗi lần bạn giao dịch, sàn thu ",["phí maker","maker-taker-fees"]," hoặc taker. Với tài khoản đăng ký qua mã giới thiệu, sàn trích một phần phí đó chia cho người giới thiệu, và nhiều chương trình chia lại một phần cho chính bạn dưới dạng hoàn phí. Tỷ lệ hoàn, thời hạn và sản phẩm áp dụng do từng sàn và từng chương trình quy định."],"Phần lớn sàn chỉ cho nhập mã giới thiệu lúc tạo tài khoản. Nếu bỏ qua bước này, bạn thường không thể thêm mã sau, trừ khi tạo tài khoản mới hợp lệ theo điều khoản của sàn.",["Với người giao dịch ",["hợp đồng tương lai","futures-contract"]," khối lượng lớn, hoàn phí cộng dồn có thể đáng kể. Hãy đọc kỹ điều kiện, cách thanh toán hoàn phí và nhập mã trên trang hoặc ứng dụng chính thức để tránh trang ",["giả mạo","phishing"],"."]],"example":["Giả sử bạn giao dịch hợp đồng tương lai với khối lượng 200.000 ",["USDT","usdt"]," mỗi tháng và phí taker 0,05%. Tổng phí là 100 USDT mỗi tháng. Nếu chương trình giới thiệu hoàn cho bạn 20% số phí đó, bạn nhận lại 20 USDT mỗi tháng, tức 240 USDT mỗi năm nếu khối lượng giữ nguyên. Đây chỉ là con số minh họa, tỷ lệ thật xem trong điều khoản chương trình."],"mistakes":["Đăng ký sàn mà quên nhập mã giới thiệu, sau đó không thể thêm vào.","Nhập mã trên trang giả mạo sàn được gửi qua tin nhắn lạ.","Giao dịch nhiều hơn chỉ để nhận hoàn phí, khiến khoản lỗ lớn hơn số tiền được hoàn."],"faq":[{"q":"Có thể thêm mã giới thiệu sau khi đăng ký không?","a":"Phần lớn sàn không cho phép. Một số chương trình có ngoại lệ trong thời gian ngắn sau khi đăng ký, hãy xem điều khoản của sàn."},{"q":"Hoàn phí được trả khi nào?","a":"Tùy sàn và chương trình: có nơi trả hằng ngày, có nơi hằng tuần, thường bằng USDT hoặc đồng phí bạn đã trả."}],"title":"Mã giới thiệu là gì? Cách nhận hoàn phí giao dịch","description":"Mã giới thiệu giúp bạn được hoàn một phần phí giao dịch trên sàn. Tìm hiểu cách hoạt động, cách tính hoàn phí và lưu ý.","related":[["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["vip-tier","Cấp VIP (bậc phí giao dịch)","Cấp VIP là hệ thống bậc phí của sàn, trong đó người dùng có khối lượng giao dịch hoặc số dư tài sản lớn hơn được hưởng mức phí maker và taker thấp hơn."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."]],"lesson":null,"coin":null,"tool":"/rates","cta":true},"tokenized-treasuries":{"slug":"tokenized-treasuries","cat":"tokenized-assets","en":"Tokenized treasuries","contentLocale":"vi","term":"Trái phiếu chính phủ token hóa (tokenized treasuries)","aka":["tokenized treasuries","trái phiếu Mỹ token hóa","T-bill token hóa"],"short":"Trái phiếu chính phủ token hóa là token đại diện cho phần sở hữu trong quỹ hoặc danh mục trái phiếu kho bạc ngắn hạn, thường là của Mỹ, mang lại lợi suất ngay trên blockchain.","body":["Nhà phát hành dùng tiền của người mua để đầu tư vào tín phiếu kho bạc Mỹ ngắn hạn hoặc quỹ thị trường tiền tệ, rồi phát hành token tương ứng. Lợi suất được cộng vào giá token hoặc trả thêm token định kỳ. Ví dụ thường được nhắc tới là BUIDL của BlackRock, BENJI của Franklin Templeton và OUSG, USDY của Ondo.",["Khác với ",["stablecoin","stablecoin"]," như ",["USDT","usdt"],", ",["USDC","usdc"]," vốn không trả lãi cho người giữ, token trái phiếu chuyển lợi suất trái phiếu cho người nắm giữ. Đổi lại, nhiều sản phẩm yêu cầu ",["KYC","kyc"],", có số tiền tối thiểu, chỉ dành cho nhà đầu tư đủ điều kiện và không mở cho người dùng tại một số quốc gia."],["Lợi suất thay đổi theo lãi suất của ngân hàng trung ương. Bạn còn chịu rủi ro ",["hợp đồng thông minh","smart-contract"],", rủi ro nhà phát hành và thời gian hoàn đổi có thể không tức thì."]],"example":"Giả sử bạn có 10.000 USDC để nhàn rỗi trong 6 tháng, và một token trái phiếu đang cho lợi suất khoảng 4,5% mỗi năm sau phí. Nếu lợi suất giữ nguyên, sau 6 tháng bạn nhận khoảng 225 USD, tức 10.000 nhân 4,5% chia 2. Nếu giữ nguyên USDC, bạn không có lãi. Nhưng nếu lãi suất ngân hàng trung ương giảm giữa kỳ, lợi suất token giảm theo và con số thực nhận sẽ thấp hơn.","mistakes":["Nghĩ lợi suất token trái phiếu là cố định cho cả năm.","Không kiểm tra điều kiện nhà đầu tư và giới hạn khu vực trước khi mua.","Coi token trái phiếu và stablecoin là một, trong khi cấu trúc pháp lý và cách hoàn đổi khác nhau."],"faq":[{"q":"Token trái phiếu khác stablecoin thế nào?","a":"Stablecoin như USDT, USDC giữ lợi suất dự trữ cho nhà phát hành. Token trái phiếu chuyển lợi suất cho người nắm giữ, nhưng thường có thêm yêu cầu KYC và điều kiện đầu tư."},{"q":"Token trái phiếu có giảm giá không?","a":"Với trái phiếu rất ngắn hạn, giá thường ổn định và tăng dần theo lãi. Tuy vậy vẫn có rủi ro nhà phát hành, hợp đồng thông minh và lãi suất thay đổi."}],"title":"Trái phiếu token hóa là gì? Tokenized treasuries","description":"Tokenized treasuries mang lợi suất trái phiếu kho bạc lên blockchain. So sánh với stablecoin, ví dụ tính lãi và điều kiện cần biết.","related":[["real-world-assets","Tài sản thực (RWA)","Tài sản thực, hay RWA, là các tài sản ngoài blockchain như trái phiếu, vàng, bất động sản hay khoản vay được token hóa để có thể nắm giữ và giao dịch trên chuỗi."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-treasuries","cta":false}});
